import { Component, input } from '@angular/core';
import { HlmProgress } from '../../../../libs/ui/progress/src';
import { HlmMuted, HlmSmall } from '@spartan-ng/helm/typography';

// Presentational: a power index drawn as a bar with its number beside it. Injects nothing.
@Component({
  selector: 'app-power-meter',
  imports: [HlmProgress, HlmMuted, HlmSmall],
  templateUrl: './power-meter.html',
  styleUrl: './power-meter.css',
})
export class PowerMeter {
  /** Power index, 0-100. */
  readonly value = input.required<number>();
  /** Names the bar for assistive technology, e.g. "Power index for Silverwing". */
  readonly label = input.required<string>();
}

